/**
 * Lemma names models write from older Mathlib, and what to use instead.
 * Pure module (no I/O at run time): used by premises.ts (hints) and modernize.ts (rewrites).
 *
 * Two tables: RENAMED_LEMMAS by hand (wins), and data/mathlib-renames.json, generated by
 * `npm run lean:renames` (scripts/mathlib_renames.py) from every `@[deprecated]` in Mathlib
 * v4.8.0 … the sandbox's version, resolved against the sandbox's own Mathlib: names it removed
 * (a proof using one fails anyway, so rewriting never breaks one) and still-deprecated pure aliases.
 */
import generated from "./data/mathlib-renames.json";

/**
 * Mathlib / Lean names that were renamed or removed, as models trained on older Mathlib still
 * write them (checked against the sandbox's Mathlib v4.33.1). Old name → name to use now.
 */
export const RENAMED_LEMMAS: Record<string, string> = {
  "Real.sqrt_eq_iff_sq_eq": "Real.sqrt_eq_iff_eq_sq",
  "Real.pi_gt_314": "Real.pi_gt_d2",
  "Real.pi_lt_315": "Real.pi_lt_d2",
  "Real.sqrt_two_mul_self": "Real.mul_self_sqrt",
  mul_self_abs: "abs_mul_abs_self",
  "sq_eq_zero'": "sq_eq_zero_iff",
  abs_le_abs_of_sq_le_sq: "sq_le_sq",
  le_or_lt: "le_or_gt",
  lt_or_le: "lt_or_ge",
  "dvd_sub'": "dvd_sub",
  "Nat.dvd_sub'": "Nat.dvd_sub",
  "Nat.succ_mul_choose_eq": "Nat.add_one_mul_choose_eq",
  "Nat.prime_def_lt''": "Nat.prime_def",
  "Nat.sq_sub_sq'": "Nat.sq_sub_sq",
  "Nat.even_mul_self_pred": "Nat.even_mul_pred_self",
  "Nat.exists_mul_emod_eq_one_of_coprime": "Nat.exists_mul_mod_eq_one_of_coprime",
  "Even.pow": "Even.pow_of_ne_zero",
  "Finset.card_insert_of_not_mem": "Finset.card_insert_of_notMem",
  "Finset.filter_card_add_filter_neg_card_eq_card": "Finset.card_filter_add_card_filter_not",
  "Finset.eq_empty_iff_forall_not_mem": "Finset.eq_empty_iff_forall_notMem",
  "Finset.not_mem_empty": "Finset.notMem_empty",
  "Set.eq_empty_of_forall_not_mem": "Set.eq_empty_of_forall_notMem",
  "le_div_iff": "le_div_iff₀",
  "div_le_iff": "div_le_iff₀",
  "lt_div_iff": "lt_div_iff₀",
  "div_lt_iff": "div_lt_iff₀",
  "le_div_iff'": "le_div_iff₀'",
  "div_le_iff'": "div_le_iff₀'",
  "lt_div_iff'": "lt_div_iff₀'",
  "div_lt_iff'": "div_lt_iff₀'",
  "div_le_div_iff": "div_le_div_iff₀",
  "Set.eq_empty_iff_forall_not_mem": "Set.eq_empty_iff_forall_notMem",
  "Set.not_mem_empty": "Set.notMem_empty",
  "Finset.eq_empty_of_forall_not_mem": "Finset.eq_empty_of_forall_notMem",
  "Finset.not_mem_singleton": "Finset.notMem_singleton",
  "Set.not_mem_singleton_iff": "Set.notMem_singleton_iff",
  "Finset.inner_mul_le_norm_mul_norm": "Finset.sum_mul_sq_le_sq_mul_sq",
  "Set.mem_setOf_eq": "Set.mem_ofPred_eq",
  "Set.mem_setOf": "Set.mem_ofPred",
  "Set.mem_def": "Set.mem_ofPred",
  "Irrational.add_rat": "Irrational.add_ratCast",
  "ZMod.natCast_self_eq_zero": "ZMod.natCast_self",
  "ZMod.natCast_zmod_eq_zero_iff_dvd": "ZMod.natCast_eq_zero_iff",
};

/** Generated renames (scripts/mathlib_renames.py), for the sandbox's Mathlib version. */
export const MATHLIB_RENAMES: Record<string, string> = (generated as { renames: Record<string, string> }).renames;
export const MATHLIB_RENAMES_VERSION: string = (generated as { mathlib: string }).mathlib;

/** The current name for an old one, or undefined: the hand table first, then the generated one. */
export function renamedTo(name: string): string | undefined {
  return Object.hasOwn(RENAMED_LEMMAS, name) ? RENAMED_LEMMAS[name] : Object.hasOwn(MATHLIB_RENAMES, name) ? MATHLIB_RENAMES[name] : undefined;
}

/**
 * Hand entries whose replacement is not the same statement (only a hint for the model, never
 * rewritten): sq_le_sq is an iff where abs_le_abs_of_sq_le_sq was an implication, …
 */
const HINT_ONLY = new Set(["Real.sqrt_two_mul_self", "abs_le_abs_of_sq_le_sq", "Set.mem_def", "Finset.inner_mul_le_norm_mul_norm"]);

/** An identifier as Lean reads it (dotted, primes, subscripts, ! and ?). */
const IDENT = /(?<![A-Za-z0-9_'.!?\u2080-\u2089])[A-Za-z_][A-Za-z0-9_'.!?\u2080-\u2089]*/g;

/** The name to write for an identifier of a proof, or undefined to keep it. */
function rewriteTo(id: string): string | undefined {
  if (HINT_ONLY.has(id)) return undefined;
  const now = renamedTo(id);
  if (now) return now;
  // `open Real`: the bare name of a hand-listed Real lemma (only those: a bare generated name could
  // be a root lemma that still exists)
  const real = `Real.${id}`;
  if (Object.hasOwn(RENAMED_LEMMAS, real) && !HINT_ONLY.has(real)) return RENAMED_LEMMAS[real].slice(5);
  return undefined;
}

/**
 * Replaces old lemma names in proof text with their current names: each identifier looked up once
 * (the generated table has thousands of entries); the full name anywhere, and for hand-listed
 * `Real.` lemmas also the bare name (used under `open Real`).
 */
export function renameOldLemmas(text: string): string {
  return text.replace(IDENT, (id) => rewriteTo(id) ?? id);
}
